  const get = i => fechado ? Q[(i + m) % m] : Q[Math.max(0, Math.min(m - 1, i))];
  const canto = i => { if (!fechado && (i === 0 || i === m - 1)) return false; const a = get(i - 1), b = get(i), c = get(i + 1);
