    });
    /* pernas: patela, dobras do joelho e do glúteo, maléolos e linhas do atlas da perna (coxa e panturrilha) */
    {const def=clamp(F.B.mus*(1-F.B.fat)*(1-0.75*F.B.fem),0,2),AP=atlasPerna();
    legs.forEach(o=>{
