      /* pé em cunha: só a divisão do dedão aparece na caixa dos dedos */
      {const Xf=v=>xv(applyA(o.Aft,v));lineT("divisao",linhaDedao(p,s,s>0?p.toesL:p.toesR,(s>0?p.halluxL:p.halluxR)||0).map(Xf),v=>v)}
