  const axes=fn=>{
    let mx=0,mn=1e9,ang=0;
    for(let i=0;i<180;i++){
      const q=xfd(fn(i/180*2*Math.PI)),r=Math.hypot(q[0],q[1]);
      if(r>mx){mx=r;ang=Math.atan2(q[1],q[0])}
