  garra: { c: 0.55, Th: -0.2, In: 0, Me: 0, An: 0, Mi: 0, sp: 0.7, op: 0.3 },
  acenar: { c: 0.08, Th: 0, In: 0, Me: 0, An: 0, Mi: 0, sp: 0.7, op: 0 },
