    const sn=Math.sin(th),cs=Math.cos(th),med=Math.max(0,-s*sn);
    return (1-0.06*Math.pow(med,2))*(1+0.12*Math.max(0,-Math.sin(ph))*Math.max(0,-cs))*(1-0.5*Math.pow(Math.max(0,Math.sin(ph)),1.3))*(1-0.18*Math.max(0,cs));
