function quadrosGluteo(p,F,ch){
  return [1,-1].map(s=>{
    const fl=(s>0?p.hipFlexL:p.hipFlexR)||0,ab=(s>0?p.hipAbdL:p.hipAbdR)||0;
    const a=fl>0?0.5*fl*(1-0.25*sstep((fl-60)/70)):0.35*fl;
